{"command":"$p = 'E:\Workspace\naumi-daily-real-acceptance-20261118\runtime\daily-real-acceptance-5f4bc98d-0866-4f64-b429-b1c196cb1ec1\home\naumi\workspaces\bot-5d0e32bc-deb1-4d50-8182-574cff3b1e4c\sales.csv'
$h0 = (Get-FileHash $p -Algorithm SHA256).Hash
$rows = Import-Csv -Path $p
"rows=$($rows.Count)"
$rows | ForEach-Object { "row: {0},{1},{2},{3}" -f $_.date,$_.channel,$_.orders,$_.amount }
$lineOrders = 0; $lineAmount = 0.0
foreach ($r in $rows) { $lineOrders += [int]$r.orders; $lineAmount += [double]$r.amount }
"methodA_linewise: orders=$lineOrders amount=$lineAmount"
$agg = $rows | Group-Object channel | ForEach-Object {
  $o=0; $a=0.0
  foreach ($x in $_.Group) { $o += [int]$x.orders; $a += [double]$x.amount }
  [pscustomobject]@{channel=$_.Name; orders=$o; amount=$a}
}
$agg | ForEach-Object { "channel: {0},{1},{2}" -f $_.channel,$_.orders,$_.amount }
$sumO = ($agg | Measure-Object orders -Sum).Sum
$sumA = ($agg | Measure-Object amount -Sum).Sum
"methodB_groupwise: orders=$sumO amount=$sumA"
"crosscheck orders: $($lineOrders -eq $sumO) ; amount: $($lineAmount -eq $sumA)"
"H1=$h0"
"distinct_dates=$((($rows | Select-Object -ExpandProperty date | Sort-Object -Unique) -join '|'))"","description":"Cross-check sales.csv two ways"}

{"command":"$dir = 'E:\Workspace\naumi-daily-real-acceptance-20261118\runtime\daily-real-acceptance-5f4bc98d-0866-4f64-b429-b1c196cb1ec1\home\naumi\workspaces\bot-5d0e32bc-deb1-4d50-8182-574cff3b1e4c'
$src = Join-Path $dir 'sales.csv'
$h = (Get-FileHash $src -Algorithm SHA256).Hash
$rows = Import-Csv -Path $src
$agg = $rows | Group-Object channel | ForEach-Object {
  $o=0; $a=0.0
  foreach ($x in $_.Group) { $o += [int]$x.orders; $a += [double]$x.amount }
  [pscustomobject]@{channel=$_.Name; orders=$o; amount=$a}
} | Sort-Object channel
$sumO = ($agg | Measure-Object orders -Sum).Sum
$sumA = ($agg | Measure-Object amount -Sum).Sum
$lines = @('channel,orders,amount')
foreach ($r in $agg) { $lines += ('{0},{1},{2}' -f $r.channel,$r.orders,($r.amount.ToString('0.##'))) }
$lines += ('total,{0},{1}' -f $sumO,($sumA.ToString('0.##')))
$csvPath = Join-Path $dir '汇总.csv'
[System.IO.File]::WriteAllLines($csvPath, $lines, (New-Object System.Text.UTF8Encoding($false)))
Get-Content -LiteralPath $csvPath
"----"
"csvLen=$((Get-Item -LiteralPath $csvPath).Length)"","description":"Generate 汇总.csv with channel totals"}

{"command":"$dir = 'E:\Workspace\naumi-daily-real-acceptance-20261118\runtime\daily-real-acceptance-5f4bc98d-0866-4f64-b429-b1c196cb1ec1\home\naumi\workspaces\bot-5d0e32bc-deb1-4d50-8182-574cff3b1e4c'
$src = Join-Path $dir 'sales.csv'
$h = (Get-FileHash $src -Algorithm SHA256).Hash
"SHA256=$h"
"bytes=$((Get-Item -LiteralPath $src).Length)"
$rows = Import-Csv -Path $src
"rows=$($rows.Count)"
$rows | ForEach-Object { "row: {0},{1},{2},{3}" -f $_.date,$_.channel,$_.orders,$_.amount }
$lo=0; $la=0.0
foreach ($r in $rows) { $lo += [int]$r.orders; $la += [double]$r.amount }
"A_linewise: orders=$lo amount=$la"
$agg = $rows | Group-Object channel | ForEach-Object {
  $o=0; $a=0.0; foreach ($x in $_.Group) { $o += [int]$x.orders; $a += [double]$x.amount }
  [pscustomobject]@{channel=$_.Name; orders=$o; amount=$a; rows=$_.Count}
} | Sort-Object channel
$agg | ForEach-Object { "channel {0}: orders={1} amount={2} rows={3}" -f $_.channel,$_.orders,$_.amount,$_.rows }
$so = ($agg | Measure-Object orders -Sum).Sum
$sa = ($agg | Measure-Object amount -Sum).Sum
"B_groupwise: orders=$so amount=$sa"
"rowsSum=$((($agg | Measure-Object rows -Sum).Sum))"
"crosscheck orders=$($lo -eq $so) amount=$($la -eq $sa)"
"dates=" + (($rows | Select-Object -ExpandProperty date | Sort-Object -Unique) -join '|')
"prevRows=3 prevSum=25"","description":"Recompute totals from updated sales.csv"}

